function asset(header, name) {
	const source = fs.readFileSync(header, 'utf8');
	const match = source.match(new RegExp(`const uint8_t ${name}\\[\\] PROGMEM = \\{([\\s\\S]*?)\\};`));
	assert.ok(match, `Missing compiled asset ${name}`);
	return zlib.gunzipSync(Buffer.from(match[1].match(/0x[0-9a-f]{2}/gi).map(value => Number(value))));
}
